mod common;

use axum::http::{Method, StatusCode};
use axum_bookclub::app;
use common::send;
use serde_json::json;

async fn make_club(router: &axum::Router) -> u64 {
    let (_, body) = send(router, Method::POST, "/api/clubs", Some(json!({"name": "C", "description": "x"}))).await;
    body["id"].as_u64().unwrap()
}

#[tokio::test]
async fn archived_club_excluded_from_list_unless_included() {
    let router = app();
    let club_id = make_club(&router).await;
    send(&router, Method::POST, &format!("/api/clubs/{club_id}/archive"), None).await;

    let (_, list) = send(&router, Method::GET, "/api/clubs", None).await;
    assert_eq!(list.as_array().unwrap().len(), 0);

    let (_, with_archived) = send(&router, Method::GET, "/api/clubs?include_archived=true", None).await;
    assert_eq!(with_archived.as_array().unwrap().len(), 1);
}

#[tokio::test]
async fn archived_club_rejects_new_members_and_new_books() {
    let router = app();
    let club_id = make_club(&router).await;
    send(&router, Method::POST, &format!("/api/clubs/{club_id}/archive"), None).await;

    let (status_member, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{club_id}/members"),
        Some(json!({"name": "Ada", "email": "a@example.com"})),
    )
    .await;
    assert_eq!(status_member, StatusCode::BAD_REQUEST);

    let (status_book, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{club_id}/books"),
        Some(json!({"title": "T", "author": "A"})),
    )
    .await;
    assert_eq!(status_book, StatusCode::BAD_REQUEST, "book creation under an archived club must be blocked too");
}

